const CSS="[hidden]{display:none!important}\n.ft{box-sizing:border-box;width:100%;height:100%;padding:10px;display:flex;flex-direction:column;gap:6px;color:var(--ink);font-size:13px;line-height:1.3;min-width:0;min-height:0;overflow:hidden}\n.ft *{box-sizing:border-box;min-width:0}\n.ft button,.ft input{font-family:inherit}\n\n/* \u9876\u680f */\n.hd{display:flex;align-items:center;gap:6px;flex:none;height:24px}\n.badge{display:inline-flex;align-items:center;gap:5px;font-size:12px;font-weight:600;color:var(--muted);white-space:nowrap}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--muted);flex:none}\n.run .dot{background:var(--accent);animation:pulse 1.6s ease-in-out infinite}\n.brk.run .dot{background:var(--accent-alt)}\n@keyframes pulse{50%{opacity:.35}}\n.sp{flex:1 1 0}\n.chip{flex:0 1 auto;border:1px solid var(--line);background:var(--soft);color:var(--ink);border-radius:999px;padding:3px 9px;font-size:12px;line-height:1.3;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chip:hover{border-color:var(--accent)}\n.vt{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n/* \u4e3b\u533a\uff1a\u5706\u73af + \u64cd\u4f5c */\n.main{flex:1 1 0;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px}\n.ringwrap{position:relative;flex:none;width:var(--rs);height:var(--rs)}\n.ring{position:absolute;inset:0;border-radius:50%;\n  background:conic-gradient(var(--accent) calc(var(--p)*1%),var(--soft) 0);\n  -webkit-mask:radial-gradient(farthest-side,transparent calc(100% - var(--rw)),var(--ink) calc(100% - var(--rw)));\n  mask:radial-gradient(farthest-side,transparent calc(100% - var(--rw)),var(--ink) calc(100% - var(--rw)))}\n.brk .ring{background:conic-gradient(var(--accent-alt) calc(var(--p)*1%),var(--soft) 0)}\n.time{position:absolute;inset:0;display:grid;place-items:center;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums;white-space:nowrap}\n.paused .time{color:var(--muted)}\n.panel{width:100%;flex:none;display:flex;flex-direction:column;gap:6px}\n.task,.num{width:100%;height:34px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font-size:14px}\n.task::placeholder{color:var(--muted)}\n.task:focus-visible,.num:focus-visible,.btn:focus-visible,.chip:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.btns{display:flex;gap:6px}\n.btn{flex:1 1 0;height:34px;padding:0 8px;border-radius:10px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-size:14px;font-weight:600;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn:active{transform:translateY(1px)}\n.now{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}\n.hint{font-size:12px;color:var(--muted);text-align:center}\n.err{font-size:12px;color:var(--ink);font-weight:600;border-left:3px solid var(--accent-alt);padding-left:6px}\n\n/* \u5217\u8868 */\n.list{flex:1 1 0;min-height:0;display:flex;flex-direction:column;gap:4px;border-top:1px solid var(--line);padding-top:6px}\n.lh{flex:none;font-size:12px;color:var(--muted)}\n.scroll{flex:1 1 0;min-height:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column}\n.scroll.full{padding-right:2px}\n.row{flex:none;display:flex;align-items:baseline;gap:8px;padding:6px 2px;border-bottom:1px dashed var(--line)}\n.rt{flex:1 1 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rm{flex:none;font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}\n.gh{flex:none;margin-top:6px;font-size:12px;font-weight:600;color:var(--muted)}\n.empty{padding:10px 2px;font-size:12px;color:var(--muted)}\n\n\n/* \u8bbe\u7f6e\u9875 */\n.sbody{flex:1 1 0;min-height:0;overflow-y:auto;display:grid;grid-template-columns:1fr;align-content:start;gap:10px}\n.fld{display:flex;flex-direction:column;gap:4px}\n.lbl{font-size:12px;color:var(--muted)}\n.numrow{display:flex;align-items:center;gap:6px}\n.num{width:84px;text-align:center}\n.unit{font-size:12px;color:var(--muted)}\n.presets{display:flex;flex-wrap:wrap;gap:4px}\n.btn.pre{flex:none;height:26px;padding:0 8px;font-size:12px;font-weight:500}\n.note{grid-column:1/-1;font-size:12px;color:var(--muted)}\n.sfoot{flex:none;display:flex;flex-direction:column;gap:6px}\n\n/* \u5c3a\u5bf8\uff1a194x194 */\n.s-3x3{--rs:84px;--rw:7px}\n.s-3x3 .time{font-size:18px}\n.s-3x3.idle{--rs:52px;--rw:5px}\n.s-3x3.idle .time{font-size:12px}\n.s-3x3.haserr .ringwrap{display:none}\n.s-3x3 .main{gap:5px}\n.s-3x3 .btn,.s-3x3 .task{height:30px}\n.s-3x3 .presets{display:none}\n.s-3x3.sub .fld{flex-direction:row;align-items:center;justify-content:space-between}\n.s-3x3.sub .num{width:70px;height:30px}\n.s-3x3.sub .sbody{gap:6px}\n\n/* 404x194\uff1a\u5de6\u73af\u53f3\u63a7 */\n.s-6x3{--rs:130px;--rw:10px}\n.s-6x3 .time{font-size:30px}\n.s-6x3 .main{flex-direction:row;gap:16px}\n.s-6x3 .panel{flex:1 1 0}\n.s-6x3.sub .sbody{grid-template-columns:1fr 1fr}\n\n/* 194x404\uff1a\u7ad6\u6392\uff0c\u4e0b\u65b9\u6eda\u52a8\u5217\u8868 */\n.s-3x6{--rs:136px;--rw:10px}\n.s-3x6 .time{font-size:28px}\n.s-3x6 .main{flex:none;gap:10px}\n.s-3x6.idle .main,.s-3x6.on .main{padding-top:4px}\n.s-3x6 .presets .btn.pre{padding:0 6px}\n\n/* 404x404\uff1a\u4e0a\u65b9\u73af+\u63a7\u5236\uff0c\u4e0b\u65b9\u6eda\u52a8\u5217\u8868 */\n.s-6x6{--rs:150px;--rw:11px;padding:12px;gap:8px}\n.s-6x6 .time{font-size:34px}\n.s-6x6 .main{flex:none;flex-direction:row;gap:20px;padding-top:2px}\n.s-6x6 .panel{flex:1 1 0}\n.s-6x6.sub .sbody{grid-template-columns:1fr 1fr}\n.s-6x6 .btn,.s-6x6 .task{height:38px}\n";
function pad2(n){return n<10?'0'+n:''+n}
function dayOf(ts){const d=new Date(ts);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())}
function hhmm(ts){const d=new Date(ts);return pad2(d.getHours())+':'+pad2(d.getMinutes())}
function clock(ms){const t=Math.max(0,Math.ceil(ms/1000));return pad2(Math.floor(t/60))+':'+pad2(t%60)}
function cfg(s){
  const c=(s&&s.settings)||{};
  const f=Math.floor(Number(c.focusMin)),b=Math.floor(Number(c.breakMin));
  return {focusMin:f>=1?f:25,breakMin:b>=1?b:5};
}
function remainOf(t,now){return t.status==='running'?t.endAt-now:t.remain}

// 一次性初始化：只补用户要求的默认时长（专注25/休息5）和空集合，不造任何记录
function initialize(s){
  const base=s||{};
  if(base.settings&&Array.isArray(base.rounds)&&'timer' in base)return s;
  return {...base,settings:base.settings||{focusMin:25,breakMin:5},rounds:Array.isArray(base.rounds)?base.rounds:[],timer:base.timer||null};
}

// 结算：把已到点的计时推进（专注结束记一轮并进入休息，休息结束回到空闲）。幂等。
function fin(s,now){
  let t=s&&s.timer;
  if(!t||t.status!=='running'||t.endAt>now)return s;
  const st=cfg(s);
  const rounds=Array.isArray(s.rounds)?s.rounds.slice():[];
  while(t&&t.status==='running'&&t.endAt<=now){
    if(t.phase==='focus'){
      if(!rounds.some(r=>r.id===t.id)){
        rounds.push({id:t.id,task:t.task,at:t.endAt,day:dayOf(t.endAt),min:Math.max(1,Math.round(t.total/60000))});
      }
      const bt=st.breakMin*60000;
      t={id:t.id+'b',phase:'break',task:t.task,total:bt,status:'running',endAt:t.endAt+bt,remain:0};
    }else{
      t=null;
    }
  }
  return {...s,rounds,timer:t};
}

function startFocus(s,task,id,now){
  const f=fin(s,now);
  if(f.timer)return f;
  const total=cfg(f).focusMin*60000;
  return {...f,timer:{id,phase:'focus',task,total,status:'running',endAt:now+total,remain:0}};
}

// 改时长：保存设置；进行中的这一轮按新时长换算（已用时间保留）
function applySettings(s,fm,bm,now){
  const f0=fin(s,now);
  let t=f0.timer;
  if(t){
    const nm=(t.phase==='focus'?fm:bm)*60000;
    if(nm!==t.total){
      const rem=remainOf(t,now);
      const left=nm-(t.total-rem);
      if(t.status==='running')t={...t,total:nm,endAt:now+left};
      else t={...t,total:nm,remain:Math.max(left,1000)};
    }
  }
  return fin({...f0,settings:{focusMin:fm,breakMin:bm},timer:t},now);
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const st=cfg(state);
  const rounds=Array.isArray(state&&state.rounds)?state.rounds:[];
  const timer=(state&&state.timer)||null;
  const today=day();
  const todayRounds=rounds.filter(r=>r.day===today).sort((a,b)=>b.at-a.at);
  const count=todayRounds.length;
  const active=!!timer;
  const running=active&&timer.status==='running';
  const isFocus=active&&timer.phase==='focus';
  const showList=size==='3x6'||size==='6x6';
  let tickId=0,focusId=0;

  const quiet=p=>{if(p&&p.catch)p.catch(()=>{})};
  const mk=(label,cls,fn)=>el('button',{type:'button',class:'btn '+cls,onclick:fn},label);
  const rowEl=r=>el('div',{class:'row'},
    el('span',{class:'rt',title:r.task},r.task),
    el('span',{class:'rm'},hhmm(r.at)+' · '+r.min+' 分'));

  function start(){
    const task=(ui.task||'').trim();
    if(!task){ui.err='请先填写这一轮要做什么';ui.focusTask=true;redraw();return}
    const id=uid();
    quiet(commit(s=>startFocus(s,task,id,Date.now()),{...ui,task:'',err:'',confirm:false}));
  }
  function pause(){
    quiet(update(s=>{
      const now=Date.now(),f=fin(s,now),t=f.timer;
      if(!t||t.status!=='running')return f;
      return {...f,timer:{...t,status:'paused',endAt:0,remain:Math.max(t.endAt-now,0)}};
    }));
  }
  function resume(){
    quiet(update(s=>{
      const now=Date.now(),t=s.timer;
      if(!t||t.status!=='paused')return s;
      return {...s,timer:{...t,status:'running',endAt:now+Math.max(t.remain,0),remain:0}};
    }));
  }
  function stop(id){
    ui.confirm=false;
    quiet(update(s=>{
      const f=fin(s,Date.now());
      if(!f.timer||f.timer.id!==id&&f.timer.id!==id+'b')return f;
      return {...f,timer:null};
    }));
  }
  function openSettings(){ui.view='settings';ui.draft=null;ui.err='';ui.confirm=false;redraw()}
  function openHistory(){ui.view='history';ui.err='';ui.confirm=false;redraw()}
  function back(){ui.view=null;ui.draft=null;ui.err='';redraw()}

  if(ui.view==='settings')return renderSettings();
  if(ui.view==='history')return renderHistory();


  // ---------- 主视图 ----------
  const now0=Date.now();
  const total=active?timer.total:st.focusMin*60000;
  const rem=active?remainOf(timer,now0):total;
  const pct=active?Math.min(100,Math.max(0,100*(1-rem/total))):0;
  const timeEl=el('div',{class:'time'},clock(rem));
  const ringEl=el('div',{class:'ring'});
  ringEl.style.setProperty('--p',pct.toFixed(2));
  const ringWrap=el('div',{class:'ringwrap',role:'timer','aria-label':'剩余时间'},ringEl,timeEl);

  const label=!active?'待开始':(isFocus?'专注':'休息')+(running?'中':'暂停');
  const header=el('div',{class:'hd'},
    el('span',{class:'badge'},el('i',{class:'dot'}),label),
    el('span',{class:'sp'}),
    el('button',{type:'button',class:'chip',onclick:openHistory,'aria-label':'查看今日完成的轮次，共'+count+'轮'},'今日 '+count+' 轮'),
    el('button',{type:'button',class:'chip',onclick:openSettings,'aria-label':'调整专注与休息时长'},'时长'));

  const errEl=el('div',{class:'err',role:'alert'},ui.err?'! '+ui.err:'');
  errEl.hidden=!ui.err;
  let inputEl=null;
  const panel=el('div',{class:'panel'});
  if(!active){
    inputEl=el('input',{class:'task',type:'text',placeholder:'这一轮要做什么？',value:ui.task||'',maxlength:'80','aria-label':'这一轮要做什么',
      oninput:e=>{ui.task=e.target.value;if(ui.err){ui.err='';errEl.hidden=true;errEl.textContent=''}},
      onkeydown:e=>{if(e.key==='Enter')start()}});
    panel.append(inputEl,errEl,mk('开始专注 '+st.focusMin+' 分钟','pri',start));
    if(size!=='3x3')panel.append(el('div',{class:'hint'},'专注 '+st.focusMin+' 分 · 休息 '+st.breakMin+' 分'));
    if(ui.focusTask){ui.focusTask=false;focusId=setTimeout(()=>inputEl.focus(),0)}
  }else{
    const nowText=ui.confirm?'放弃后这一轮不计入完成数':(isFocus?timer.task:'刚完成：'+timer.task);
    panel.append(el('div',{class:'now',title:timer.task},nowText));
    const btns=el('div',{class:'btns'});
    if(ui.confirm){
      btns.append(mk('确认放弃','pri',()=>stop(timer.id)),mk('取消','',()=>{ui.confirm=false;redraw()}));
    }else{
      btns.append(running?mk('暂停','pri',pause):mk('继续','pri',resume),
        isFocus?mk('放弃本轮','',()=>{ui.confirm=true;redraw()}):mk('跳过休息','',()=>stop(timer.id)));
    }
    panel.append(btns);
  }

  const cls='ft s-'+size+(active?(isFocus?' on focus':' on brk'):' idle')+(active&&!running?' paused':'')+(ui.err?' haserr':'');
  const kids=[header,el('div',{class:'main'},ringWrap,panel)];
  if(showList){
    kids.push(el('div',{class:'list'},
      el('div',{class:'lh'},'今日完成 '+count+' 轮'),
      el('div',{class:'scroll'},...(count?todayRounds.map(rowEl):[el('div',{class:'empty'},'今天还没有完成的专注轮次')]))));
  }
  root.appendChild(el('div',{class:cls},...kids));

  if(running){
    let fired=false;
    tickId=setInterval(()=>{
      const left=timer.endAt-Date.now();
      timeEl.textContent=clock(left);
      ringEl.style.setProperty('--p',Math.min(100,Math.max(0,100*(1-left/timer.total))).toFixed(2));
      if(left<=0&&!fired){
        fired=true;
        clearInterval(tickId);
        quiet(update(s=>fin(s,Date.now())));
      }
    },500);
  }
  return ()=>{clearInterval(tickId);clearTimeout(focusId)};


  // ---------- 调整时长 ----------
  function renderSettings(){
    if(!ui.draft)ui.draft={focus:String(st.focusMin),brk:String(st.breakMin)};
    const d=ui.draft;
    const eEl=el('div',{class:'err',role:'alert'},ui.err?'! '+ui.err:'');
    eEl.hidden=!ui.err;
    const save=()=>{
      const f=Number(d.focus),b=Number(d.brk);
      if(d.focus===''||!Number.isInteger(f)||f<1||f>180){ui.err='专注时长需为 1–180 的整数分钟';redraw();return}
      if(d.brk===''||!Number.isInteger(b)||b<1||b>60){ui.err='休息时长需为 1–60 的整数分钟';redraw();return}
      quiet(commit(s=>applySettings(s,f,b,Date.now()),{...ui,view:null,draft:null,err:''}));
    };
    const field=(name,key,max,presets)=>{
      const inp=el('input',{class:'num',type:'number',min:'1',max:String(max),step:'1',inputmode:'numeric','aria-label':name+'（分钟）',value:d[key],
        oninput:e=>{d[key]=e.target.value;if(ui.err){ui.err='';eEl.hidden=true;eEl.textContent=''}},
        onkeydown:e=>{if(e.key==='Enter')save()}});
      const pre=el('div',{class:'presets'},...presets.map(v=>mk(v+' 分','pre',()=>{d[key]=String(v);inp.value=String(v)})));
      return el('div',{class:'fld'},el('span',{class:'lbl'},name),el('span',{class:'numrow'},inp,el('span',{class:'unit'},'分钟')),pre);
    };
    const body=el('div',{class:'sbody'},field('专注时长','focus',180,[15,25,45,60]),field('休息时长','brk',60,[5,10,15]));
    if(active&&size!=='3x3')body.append(el('div',{class:'note'},'进行中的这一轮也会按新时长换算，已用时间保留。'));
    root.appendChild(el('div',{class:'ft sub s-'+size},
      el('div',{class:'hd'},el('button',{type:'button',class:'chip',onclick:back},'‹ 返回'),el('span',{class:'vt'},'调整时长')),
      body,
      el('div',{class:'sfoot'},eEl,mk('保存','pri',save))));
  }

  // ---------- 完成记录（全部轮次，按天分组，可滚动） ----------
  function renderHistory(){
    const all=rounds.slice().sort((a,b)=>b.at-a.at);
    const yest=dayOf(Date.now()-864e5);
    const cnt={};
    all.forEach(r=>{cnt[r.day]=(cnt[r.day]||0)+1});
    const items=[];
    let cur='';
    all.forEach(r=>{
      if(r.day!==cur){
        cur=r.day;
        items.push(el('div',{class:'gh'},(cur===today?'今天':cur===yest?'昨天':cur)+' · '+cnt[cur]+' 轮'));
      }
      items.push(rowEl(r));
    });
    if(!items.length)items.push(el('div',{class:'empty'},'还没有完成的专注轮次'));
    root.appendChild(el('div',{class:'ft sub s-'+size},
      el('div',{class:'hd'},el('button',{type:'button',class:'chip',onclick:back},'‹ 返回'),el('span',{class:'vt'},'完成记录 · 今日 '+count+' 轮')),
      el('div',{class:'scroll full'},...items)));
  }
}

